        let rust_limit = FILE_LIMITS[0];
        write_rust_file_with_lines(&src_dir.join("near_limit.rs"), rust_limit.warn_lines + 1);
        write_rust_file_with_lines(&src_dir.join("over_limit.rs"), rust_limit.max_lines + 1);
