/// path component. A substring test hid every workflow from the gate --
/// `.github/workflows/release.yml` contains `.git` -- and would likewise skip
/// any path with `target` or `node_modules` inside a longer segment.
fn should_exclude(path: &Path) -> bool {
    let path_str = normalized_path(path);

    path_str
        .split('/')
        .any(|component| EXCLUDE_PATTERNS.contains(&component))
        || EXCLUDE_PATH_FRAGMENTS
            .iter()
            .any(|fragment| path_str.contains(fragment))
}

fn is_worker_js_path(path: &Path) -> bool {
    let path_str = normalized_path(path);
    let has_js_extension = path
        .extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| extension.eq_ignore_ascii_case("js"));
    path_str.ends_with("src/web/formal_ai_worker.js")
        || (path_str.contains("/src/web/worker/") && has_js_extension)
}

/// Only workflows this repository owns are measured. `docs/case-studies/**`
/// holds verbatim copies of other projects' pipelines as evidence; reformatting
/// them to fit our ceiling would destroy the thing they document.
fn is_workflow_yaml_path(path: &Path) -> bool {
    let path_str = normalized_path(path);
    let has_yaml_extension = path
        .extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| {
            extension.eq_ignore_ascii_case("yml") || extension.eq_ignore_ascii_case("yaml")
        });

    has_yaml_extension && (path_str.starts_with(".github/") || path_str.contains("/.github/"))
}

fn file_limit(path: &Path) -> Option<&'static FileLimit> {
    if is_worker_js_path(path) {
        return Some(&WORKER_JS_LIMIT);
    }

    if is_workflow_yaml_path(path) {
        return Some(&WORKFLOW_YAML_LIMIT);
    }

    let ext = path.extension().and_then(|ext| ext.to_str())?;

    FILE_LIMITS.iter().find(|limit| limit.extension == ext)
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Finding {
    file: String,
    lines: usize,
    max_lines: usize,
    warn_lines: usize,
    label: &'static str,
}

#[derive(Debug, PartialEq, Eq)]
struct EmbeddedDataFinding {
    file: String,
    line: usize,
    message: String,
}

#[derive(Debug, PartialEq, Eq)]
struct CheckResult {
    warnings: Vec<Finding>,
    violations: Vec<Finding>,
    embedded_data_violations: Vec<EmbeddedDataFinding>,
}

#[derive(Debug, PartialEq, Eq)]
enum LineStatus {
    WithinLimit,
    Warning,
    Violation,
}

const fn classify_line_count(line_count: usize, limit: &FileLimit) -> LineStatus {
    if line_count > limit.max_lines {
        LineStatus::Violation
    } else if line_count > limit.warn_lines {
        LineStatus::Warning
    } else {
        LineStatus::WithinLimit
    }
}

fn relative_path(path: &Path, cwd: &Path) -> String {
    let relative = path
        .strip_prefix(cwd)
        .unwrap_or(path)
        .to_string_lossy()
        .to_string();

    relative.replace(std::path::MAIN_SEPARATOR, "/")
}

fn is_embedded_lino_data_line(line: &str) -> bool {
    let trimmed = line.trim_start();
    let declares_lino = (trimmed.starts_with("const ")
        || trimmed.starts_with("let ")
        || trimmed.starts_with("var "))
        && trimmed.contains("_LINO")
        && trimmed.contains('=');

    declares_lino && (trimmed.contains("= [") || trimmed.contains("= `"))
}

fn check_directory(cwd: &Path) -> CheckResult {
    let mut result = CheckResult {
        warnings: Vec::new(),
        violations: Vec::new(),
        embedded_data_violations: Vec::new(),
    };

    for entry in WalkDir::new(cwd)
        .into_iter()
        .filter_map(std::result::Result::ok)
        .filter(|e| e.file_type().is_file())
    {
        let path = entry.path();

        if should_exclude(path) {
            continue;
        }

        let limit = file_limit(path);
        let check_worker_data = is_worker_js_path(path);

        if limit.is_none() && !check_worker_data {
            continue;
        }

        match fs::read_to_string(path) {
            Ok(content) => {
                if let Some(limit) = limit {
                    let line_count = content.lines().count();

                    let finding = Finding {
                        file: relative_path(path, cwd),
                        lines: line_count,
                        max_lines: limit.max_lines,
                        warn_lines: limit.warn_lines,
                        label: limit.label,
                    };

                    match classify_line_count(line_count, limit) {
                        LineStatus::Violation => result.violations.push(finding),
                        LineStatus::Warning => result.warnings.push(finding),
                        LineStatus::WithinLimit => {}
                    }
                }

                if check_worker_data {
                    for (index, line) in content.lines().enumerate() {
                        if is_embedded_lino_data_line(line) {
                            result.embedded_data_violations.push(EmbeddedDataFinding {
                                file: relative_path(path, cwd),
                                line: index + 1,
                                message: "Worker JavaScript must load Links Notation data from data/seed via seed_loader.js, not embed _LINO arrays or template literals.".to_string(),
                            });
                        }
                    }
                }
            }
            Err(error) => {
                eprintln!("Warning: Could not read {}: {error}", path.display());
            }
        }
    }

    result
}

fn escape_annotation_property(value: &str) -> String {
    value
        .replace('%', "%25")
        .replace('\r', "%0D")
        .replace('\n', "%0A")
        .replace(':', "%3A")
        .replace(',', "%2C")
}

fn escape_annotation_message(value: &str) -> String {
    value
        .replace('%', "%25")
        .replace('\r', "%0D")
        .replace('\n', "%0A")
}

fn warning_annotation(finding: &Finding) -> String {
    let message = format!(
        "{} file has {} lines (approaching limit of {}). Consider extracting content to keep at or below {} lines and prevent review and merge conflicts.",
        finding.label, finding.lines, finding.max_lines, finding.warn_lines
    );

    format!(
        "::warning file={}::{}",
        escape_annotation_property(&finding.file),
        escape_annotation_message(&message)
    )
}

fn warnings_for_growing_paths<'a>(
    warnings: &'a [Finding],
    growing_paths: &[String],
) -> Vec<&'a Finding> {
    warnings
        .iter()
        .filter(|finding| growing_paths.contains(&finding.file))
        .collect()
}

fn growing_paths_from_numstat(numstat: &str) -> Vec<String> {
    numstat
        .lines()
        .filter_map(|line| {
            let mut fields = line.splitn(3, '\t');
            let added = fields.next()?.parse::<usize>().ok()?;
            let removed = fields.next()?.parse::<usize>().ok()?;
            let path = fields.next()?;
            (added > removed).then(|| path.to_string())
        })
        .collect()
}

#[cfg(not(test))]
fn growing_paths_since(base: &str) -> Option<Vec<String>> {
    if base.is_empty() || base.chars().all(|character| character == '0') {
        return None;
    }

    let output = Command::new("git")
        .args([
            "diff",
            "--numstat",
            "--diff-filter=ACMR",
            base,
            "HEAD",
            "--",
        ])
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }

    Some(growing_paths_from_numstat(&String::from_utf8_lossy(
        &output.stdout,
    )))
}

#[cfg(not(test))]
fn print_warnings(warnings: &[Finding]) {
    if warnings.is_empty() {
        return;
    }

    for warning in warnings {
        let annotation = warning_annotation(warning);
        println!("{annotation}");
        println!(
            "WARNING: {} has {} lines (approaching {} limit of {}, warning threshold: {})",
            warning.file, warning.lines, warning.label, warning.max_lines, warning.warn_lines
        );
    }

    println!();
    println!("The following files are approaching their configured line limits:");
    for warning in warnings {
        println!("  {}", warning.file);
    }
    println!("\nConsider extracting code to prevent concurrent PR merge limit violations.\n");
}

#[cfg(not(test))]
fn print_violations(violations: &[Finding]) {
    if violations.is_empty() {
        return;
    }

    println!("Found files exceeding the line limit:\n");
    for violation in violations {
        println!(
            "  {}: {} lines (exceeds {} limit of {})",
            violation.file, violation.lines, violation.label, violation.max_lines
        );
    }
    println!("\nPlease refactor or split these files to stay under their limits\n");
}

#[cfg(not(test))]
fn print_embedded_data_violations(violations: &[EmbeddedDataFinding]) {
    if violations.is_empty() {
        return;
    }

    println!("Found embedded Links Notation data in worker JavaScript:\n");
    for violation in violations {
        println!(
            "  {}:{}: {}",
            violation.file, violation.line, violation.message
        );
    }
    println!("\nMove worker seed data to data/seed and load it through seed_loader.js\n");
}

#[cfg(not(test))]
fn main() {
    println!(
        "\nChecking configured file line limits for Rust, Links Notation, worker JavaScript, and GitHub Actions workflow files...\n"
    );

    let cwd = std::env::current_dir().expect("Failed to get current directory");
    let result = check_directory(&cwd);
    let warning_base = std::env::var("FILE_SIZE_WARNING_BASE").unwrap_or_default();
    if let Some(growing_paths) = growing_paths_since(&warning_base) {
        let warnings = warnings_for_growing_paths(&result.warnings, &growing_paths);
        let warnings: Vec<Finding> = warnings.into_iter().cloned().collect();
        print_warnings(&warnings);
    } else {
        print_warnings(&result.warnings);
    }

    if result.violations.is_empty() && result.embedded_data_violations.is_empty() {
        println!("All checked files are within their line limits\n");
        exit(0);
    } else {
        print_violations(&result.violations);
        print_embedded_data_violations(&result.embedded_data_violations);
        exit(1);
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fmt::Write as _;
    use std::path::PathBuf;
    use std::time::{SystemTime, UNIX_EPOCH};

    fn temp_dir(name: &str) -> PathBuf {
        let nanos = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let path = std::env::temp_dir().join(format!("check-file-size-{name}-{nanos}"));
        fs::create_dir_all(&path).unwrap();
        path
    }

    fn write_rust_file_with_lines(path: &Path, line_count: usize) {
        write_file_with_lines(path, line_count);
    }

    fn write_lino_file_with_lines(path: &Path, line_count: usize) {
        write_file_with_lines(path, line_count);
    }

    fn write_js_file_with_lines(path: &Path, line_count: usize) {
        write_file_with_lines(path, line_count);
    }

    fn write_file_with_lines(path: &Path, line_count: usize) {
        let mut content = String::new();
        for line in 1..=line_count {
            writeln!(&mut content, "// line {line}").unwrap();
        }
        fs::write(path, content).unwrap();
    }

    #[test]
    fn classifies_warning_band_without_blocking() {
        let rust_limit = &FILE_LIMITS[0];
        assert_eq!(
            classify_line_count(rust_limit.warn_lines, rust_limit),
            LineStatus::WithinLimit
        );
        assert_eq!(
            classify_line_count(rust_limit.warn_lines + 1, rust_limit),
            LineStatus::Warning
        );
        assert_eq!(
            classify_line_count(rust_limit.max_lines, rust_limit),
            LineStatus::Warning
        );
    }

    #[test]
    fn classifies_hard_limit_violations() {
        let rust_limit = &FILE_LIMITS[0];
        assert_eq!(
            classify_line_count(rust_limit.max_lines + 1, rust_limit),
            LineStatus::Violation
        );
    }

    #[test]
    fn check_directory_reports_warning_and_violation_separately() {
        let repo = temp_dir("thresholds");
        let src_dir = repo.join("src");
        fs::create_dir_all(&src_dir).unwrap();
        let rust_limit = FILE_LIMITS[0];
        write_rust_file_with_lines(&src_dir.join("near_limit.rs"), rust_limit.warn_lines + 1);
        write_rust_file_with_lines(&src_dir.join("over_limit.rs"), rust_limit.max_lines + 1);
        write_rust_file_with_lines(&src_dir.join("small.rs"), rust_limit.warn_lines);

        let result = check_directory(&repo);

        assert_eq!(
            result.warnings,
            vec![Finding {
                file: "src/near_limit.rs".to_string(),
                lines: rust_limit.warn_lines + 1,
                max_lines: rust_limit.max_lines,
                warn_lines: rust_limit.warn_lines,
                label: rust_limit.label,
            }]
        );
        assert_eq!(
            result.violations,
            vec![Finding {
                file: "src/over_limit.rs".to_string(),
                lines: rust_limit.max_lines + 1,
                max_lines: rust_limit.max_lines,
                warn_lines: rust_limit.warn_lines,
                label: rust_limit.label,
            }]
        );
    }

    #[test]
    fn warning_annotations_are_limited_to_growing_files() {
        let warnings = vec![
            Finding {
                file: "src/unchanged.rs".to_string(),
                lines: 910,
                max_lines: 1_000,
                warn_lines: 900,
                label: "Rust",
            },
            Finding {
                file: "src/changed.rs".to_string(),
                lines: 920,
                max_lines: 1_000,
                warn_lines: 900,
                label: "Rust",
            },
        ];

        assert_eq!(
            warnings_for_growing_paths(&warnings, &["src/changed.rs".to_string()]),
            vec![&warnings[1]]
        );
    }

    #[test]
    fn numstat_selects_only_files_with_net_line_growth() {
        let numstat = "12\t0\tsrc/growing.rs\n3\t3\tsrc/unchanged.rs\n1\t8\tsrc/shrinking.rs\n-\t-\tassets/binary.png\n";

        assert_eq!(
            growing_paths_from_numstat(numstat),
            vec!["src/growing.rs".to_string()]
        );
    }

    #[test]
    fn check_directory_enforces_lino_limit() {
        let repo = temp_dir("lino-thresholds");
        let data_dir = repo.join("data");
        fs::create_dir_all(&data_dir).unwrap();
        let lino_limit = FILE_LIMITS[1];
        write_lino_file_with_lines(&data_dir.join("oversized.lino"), lino_limit.max_lines + 1);

        let result = check_directory(&repo);

        assert_eq!(
            result.violations,
            vec![Finding {
                file: "data/oversized.lino".to_string(),
                lines: lino_limit.max_lines + 1,
                max_lines: lino_limit.max_lines,
                warn_lines: lino_limit.warn_lines,
                label: lino_limit.label,
            }]
        );
    }

    #[test]
    fn check_directory_enforces_split_worker_js_limit() {
        let repo = temp_dir("worker-js-thresholds");
        let worker_dir = repo.join("src/web/worker");
        fs::create_dir_all(&worker_dir).unwrap();
        write_js_file_with_lines(
            &worker_dir.join("formal_ai_worker_00.js"),
            WORKER_JS_LIMIT.max_lines + 1,
        );

        let result = check_directory(&repo);

        assert_eq!(
            result.violations,
            vec![Finding {
                file: "src/web/worker/formal_ai_worker_00.js".to_string(),
                lines: WORKER_JS_LIMIT.max_lines + 1,
                max_lines: WORKER_JS_LIMIT.max_lines,
                warn_lines: WORKER_JS_LIMIT.warn_lines,
                label: WORKER_JS_LIMIT.label,
            }]
        );
    }

    #[test]
    fn check_directory_does_not_apply_worker_limit_to_legacy_js() {
        let repo = temp_dir("legacy-js-thresholds");
        let app_dir = repo.join("src/web/app");
        fs::create_dir_all(&app_dir).unwrap();
        write_js_file_with_lines(&app_dir.join("main.js"), WORKER_JS_LIMIT.max_lines + 1);

        let result = check_directory(&repo);

        assert_eq!(result.violations, Vec::new());
        assert_eq!(result.warnings, Vec::new());
    }

    #[test]
    fn check_directory_rejects_embedded_worker_lino_data() {
        let repo = temp_dir("embedded-worker-lino");
        let worker_dir = repo.join("src/web/worker");
        fs::create_dir_all(&worker_dir).unwrap();
        fs::write(
            worker_dir.join("formal_ai_worker_00.js"),
            "const MEANINGS_LINO = [\n  \"meaning fact\",\n].join(\"\\n\");\n",
        )
        .unwrap();

        let result = check_directory(&repo);

        assert_eq!(
            result.embedded_data_violations,
            vec![EmbeddedDataFinding {
                file: "src/web/worker/formal_ai_worker_00.js".to_string(),
                line: 1,
                message: "Worker JavaScript must load Links Notation data from data/seed via seed_loader.js, not embed _LINO arrays or template literals.".to_string(),
            }]
        );
    }

    /// Issue #812: `.github/workflows/**` matched the `.git` exclusion as a
    /// substring, so every workflow was invisible to this gate and
    /// `release.yml` grew to 1824 lines with CI green.
    #[test]
    fn check_directory_measures_github_workflows() {
        let repo = temp_dir("github-workflows");
        let workflows = repo.join(".github/workflows");
        fs::create_dir_all(&workflows).unwrap();
        write_file_with_lines(
            &workflows.join("release.yml"),
            WORKFLOW_YAML_LIMIT.max_lines + 1,
        );

        let result = check_directory(&repo);

        assert_eq!(
            result.violations,
            vec![Finding {
                file: ".github/workflows/release.yml".to_string(),
                lines: WORKFLOW_YAML_LIMIT.max_lines + 1,
                max_lines: WORKFLOW_YAML_LIMIT.max_lines,
                warn_lines: WORKFLOW_YAML_LIMIT.warn_lines,
                label: WORKFLOW_YAML_LIMIT.label,
            }]
        );
    }

    /// Case studies quote other projects' pipelines verbatim as evidence;
    /// trimming them to our ceiling would destroy what they document.
    #[test]
    fn check_directory_does_not_measure_quoted_case_study_workflows() {
        let repo = temp_dir("case-study-workflows");
        let case_study = repo.join("docs/case-studies/issue-561/template-comparison/js");
        fs::create_dir_all(&case_study).unwrap();
        write_file_with_lines(
            &case_study.join("release.yml"),
